AND EXISTS (SELECT 1 FROM customer c WHERE c.id = i.customer_id AND c.deleted = FALSE

    AND FALSE

    AND c.seller_id IN
        #{id}

)
AND (i.source_type = 'BALANCE_RECHARGE' OR (i.source_type = 'SALES_ORDER' AND EXISTS (
    SELECT 1 FROM sales_order so WHERE so.id = i.source_id AND so.deleted = FALSE

        AND FALSE

        AND so.seller_id IN
            #{id}

    )))

mapper.select:
SELECT i.* FROM payment_intent i
WHERE i.deleted = FALSE

AND i.source_type = #{query.sourceType}
AND customer_id = #{query.customerId}
AND source_id = #{query.sourceId}
AND provider = #{query.provider}
AND method = #{query.method}
AND status = #{query.status}

    AND (intent_no ILIKE CONCAT('%', #{query.keyword}, '%')
     OR source_no_snapshot ILIKE CONCAT('%', #{query.keyword}, '%')
     OR customer_name_snapshot ILIKE CONCAT('%', #{query.keyword}, '%'))

ORDER BY created_at DESC, id DESC

SELECT COALESCE(SUM(amount), 0)
FROM payment_intent
WHERE source_type = #{sourceType}
  AND source_id = #{sourceId}
  AND status = 'SUCCEEDED'
  AND deleted = FALSE
